      ('pack2-forever-stamp', 'easy', 'everyday-products', 'How much does one USPS Forever stamp cost right now?', 'A single First-Class Forever stamp, after the U.S. Postal Service''s July 12, 2026 price change.', '/items/postage-stamp.svg', 'Illustration of a postage stamp with a star and perforated edges', 0.82, 'USPS retail price of one First-Class Forever stamp', '2026-07-12', 'A Forever stamp went from 78 cents to 82 cents on July 12, 2026. A book of 20 costs $16.40.', 'How Much Are Stamps in 2026? Forever Stamp Price + Full USPS Rate Chart', 'The Letter Pilot', 'https://theletterpilot.com/guides/how-much-are-stamps', 'The latest increase moved a Forever Stamp from $0.78 to $0.82.', 'Secondary source. Confirm on usps.com (Postal Store) before verifying.'),
      ('pack2-netflix-standard', 'easy', 'entertainment', 'How much is a Netflix Standard plan per month in the U.S.?', 'The Standard plan without ads, monthly price after Netflix''s March 2026 increase.', '/items/tv-streaming.svg', 'Illustration of a TV showing a grid of colorful movie tiles and a play button', 19.99, 'Netflix U.S. monthly price, Standard plan (no ads)', '2026-03-26', 'Netflix raised U.S. prices in March 2026: Standard with ads is $8.99, Standard is $19.99 and Premium is $26.99 a month.', 'Netflix raising prices again on all plans: How much more you''ll be paying', 'FOX 5 New York', 'https://www.fox5ny.com/news/netflix-raising-prices-again-all-plans-how-much-more-youll-be-paying', 'Standard: $19.99/month', 'Confirm on help.netflix.com (plans and pricing) before verifying.'),
      ('pack2-playstation-5', 'easy', 'technology', 'How much does a PlayStation 5 console cost in the U.S.?', 'The standard PS5 with a disc drive (not the Digital Edition or Pro), Sony''s U.S. price since April 2, 2026.', '/items/game-console.svg', 'Illustration of a white game console standing upright next to a controller', 649.99, 'Sony''s U.S. retail price for the standard PS5', '2026-04-02', 'Sony raised PS5 prices on April 2, 2026: the PS5 went from $549.99 to $649.99, the Digital Edition to $599.99 and the PS5 Pro to $899.99.', 'The PlayStation Portal, PS5, and PS5 Pro are getting huge price hikes next month, Sony confirms', 'TechRadar', 'https://www.techradar.com/gaming/the-playstation-portal-ps5-and-ps5-pro-are-getting-huge-price-hikes-next-month-sony-confirms', 'PS5 – $649.99 (up from $549.99)', ''),
      ('pack2-airpods-pro-3', 'easy', 'technology', 'What is Apple''s price for AirPods Pro 3?', 'Apple''s regular U.S. retail price, not a store sale.', '/items/earbuds.svg', 'Illustration of white wireless earbuds next to their charging case', 249.00, 'Apple''s U.S. retail price', '2025-09-09', 'Apple launched AirPods Pro 3 in September 2025 at $249 in the U.S. Retailers like Amazon often sell them for $199 to $210.', 'AirPods Pro 3: price, features, and everything you need to know', 'What Hi-Fi?', 'https://www.whathifi.com/advice/airpods-pro-3-release-date-news-price-rumours-and-leaks', 'Apple''s new flagship wireless earbuds cost £219 / $249 / AU$429.', 'Confirm on apple.com/airpods-pro before verifying.'),
      ('pack2-amazon-prime-annual', 'easy', 'everyday-products', 'How much is a yearly Amazon Prime membership in the U.S.?', 'The standard annual plan (not monthly, student or Access), 2026.', '/items/delivery-box.svg', 'Illustration of a taped cardboard shipping box with a label', 139.00, 'Amazon''s U.S. annual Prime membership price', '2026-08-12', 'Amazon Prime has cost $139 a year in the U.S. since 2022. Paying monthly costs $14.99 a month, about $180 a year.', 'How Much Is Amazon Prime?', 'DealNews', 'https://www.dealnews.com/features/Amazon/How-Much-Is-Amazon-Prime/', 'A standard 2026 Amazon Prime membership currently costs $139 per year', 'Confirm on amazon.com/prime before verifying.'),
      ('pack2-harvard-year', 'medium', 'personal-finance', 'What does one year at Harvard cost before financial aid (2026–27)?', 'Harvard''s full cost of attendance for the 2026–27 school year: tuition, housing, food and fees.', '/items/college.svg', 'Illustration of a red-brick college hall with a clock tower and a graduation cap', 91634.00, 'Harvard College total cost of attendance, 2026–27', '2026-06-29', 'Harvard raised its total cost of attendance by more than 5% to $91,634 for 2026–27. Most students pay less after financial aid.', 'Harvard sticker price rises above $91,000', 'The Harvard Crimson', 'https://www.thecrimson.com/article/2026/6/29/harvard-sticker-price-inflation/', 'For the 2026-27 academic year, Harvard will raise its total cost of attendance by more than five percent to $91,634.', ''),
      ('pack2-average-wedding', 'medium', 'personal-finance', 'How much does the average wedding in the U.S. cost?', 'Average total spend for couples married in 2025, from The Knot 2026 Real Weddings Study.', '/items/wedding-cake.svg', 'Illustration of a three-tier white wedding cake with a red heart on top', 34200.00, 'Average total wedding cost (The Knot 2026 Real Weddings Study)', '2026-02-01', 'The Knot surveyed more than 10,000 U.S. couples married in 2025 and found the average wedding cost $34,200, not counting the engagement ring or honeymoon.', 'The Average Wedding Cost, According to The Knot Data', 'The Knot', 'https://www.theknot.com/content/average-wedding-cost', 'The overall average wedding cost is $34,200, according to The Knot 2026 Real Weddings Study', ''),
      ('pack2-average-new-car', 'medium', 'business-and-markets', 'What did the average new car sell for in the U.S. in September 2026?', 'Kelley Blue Book''s average transaction price: what buyers actually paid for a new vehicle in September 2026.', '/items/suv.svg', 'Illustration of a blue SUV with a yellow price tag', 50562.00, 'Kelley Blue Book average transaction price, new vehicles, September 2026', '2026-10-13', 'Buyers paid an average of $50,562 for a new vehicle in September 2026, just under the record of $50,614 set in December 2025.', 'September 2026 Kelley Blue Book ATP Report', 'Cox Automotive', 'https://www.coxautoinc.com/insights/sept-2026-atp-report/', 'The September average transaction price, or ATP, reached $50,562', ''),
      ('pack2-aaa-car-ownership', 'medium', 'personal-finance', 'How much does it cost per year to own and drive a new car?', 'AAA''s 2026 estimate of the average yearly cost of a new vehicle, counting everything (fuel, insurance, depreciation, maintenance and more) over five years and 75,000 miles.', '/items/car-keys.svg', 'Illustration of a car key fob on a key ring next to a bill', 12863.00, 'AAA Your Driving Costs 2026, average annual cost of a new vehicle', '2026-09-15', 'AAA''s 2026 Your Driving Costs study puts the average cost of owning and operating a new vehicle at $12,863 a year. Depreciation is the biggest single expense.', 'AAA estimates new vehicle ownership costs at $12,863 a year', 'FingerLakes1.com', 'https://www.fingerlakes1.com/2026/09/15/aaa-estimates-new-vehicle-ownership-costs-at-12863-a-year/', 'Owning and operating a new vehicle costs an average of $12,863 a year', 'Confirm on newsroom.aaa.com before verifying.'),
      ('pack2-median-home-price', 'medium', 'real-estate', 'What was the median price of a home sold in the U.S. in September 2026?', 'The national median price of existing (previously owned) homes sold in September 2026, per the National Association of Realtors.', '/items/house.svg', 'Illustration of a house with a brown roof and a sign in the front yard', 417500.00, 'NAR national median existing-home sales price, September 2026', '2026-10-16', 'The median existing-home price was $417,500 in September 2026, up 1.3% from a year earlier. Half of homes sold for more, half for less.', 'Existing Home Sales: NAR inventory and prices', 'Mortgage News Daily', 'https://www.mortgagenewsdaily.com/news/10162026-existing-home-sales-nar-inventory-prices-appr', 'The median existing-home price reached $417,500, up 1.3% from September 2025.', 'Confirm against NAR''s September 2026 release on nar.realtor before verifying.'),
      ('pack2-ohtani-contract', 'hard', 'sports', 'How much is Shohei Ohtani''s contract with the Los Angeles Dodgers worth?', 'The total value of the 10-year deal he agreed to in December 2023.', '/items/baseball.svg', 'Illustration of a baseball bat and ball next to a signed contract', 700000000.00, 'Total contract value', '2023-12-09', 'Ohtani agreed to a 10-year, $700 million contract with the Dodgers in December 2023, the largest in pro sports history at the time. Most of the money is deferred until after the contract ends.', 'Shohei Ohtani agrees to $700 million, 10-year contract with Los Angeles Dodgers', 'ABC7 (Associated Press)', 'https://abc7.com/post/shohei-ohtani-dodgers-deal-los-angeles-contract-mlb/14158641/', 'has agreed to a record $700 million, 10-year contract with the Los Angeles Dodgers', ''),
      ('pack2-jordan-1998-jersey', 'hard', 'sports', 'How much did Michael Jordan''s jersey from Game 1 of the 1998 NBA Finals sell for at auction?', 'The red Chicago Bulls jersey sold by Sotheby''s in September 2022, final price.', '/items/basketball-jersey.svg', 'Illustration of a red basketball jersey with the number 23', 10100000.00, 'Final auction price', '2022-09-15', 'Sotheby''s sold the jersey Jordan wore in Game 1 of the 1998 Finals, the ''Last Dance'' season, for $10.1 million in September 2022, a record for game-worn sports memorabilia at the time.', 'A Jersey Michael Jordan Wore in the Famous ''Last Dance'' 1998 NBA Finals Just Sold at Sotheby''s for $10.1 Million', 'Artnet News', 'https://news.artnet.com/market/a-jersey-michael-jordan-wore-10-1-million-2176588', 'The red Chicago Bulls jersey worn by Michael Jordan in Game 1 of the 1998 NBA Finals just sold for a staggering $10.1 million.', ''),
      ('pack2-twitter-acquisition', 'hard', 'business-and-markets', 'How much did Elon Musk pay to buy Twitter?', 'The approximate total value of the deal, which closed on October 28, 2022.', '/items/social-app.svg', 'Illustration of a phone showing a social media feed with speech bubbles', 44000000000.00, 'Approximate total transaction value', '2022-10-28', 'Musk bought Twitter for about $44 billion ($54.20 a share). The deal closed on October 28, 2022, and the company was later renamed X.', 'Elon Musk Completes Twitter Acquisition', 'Simpson Thacher & Bartlett', 'https://webdev.stblaw.com/about-us/news/view/2022/10/28/elon-musk-completes-twitter-acquisition', 'in a transaction valued at approximately $44 billion', 'Consider replacing the source link with the www.stblaw.com address of the same page.'),
      ('pack2-burj-khalifa', 'hard', 'science-and-infrastructure', 'How much did the Burj Khalifa in Dubai cost to build?', 'The final construction cost of the world''s tallest building, which opened in January 2010.', '/items/skyscraper.svg', 'Illustration of a very tall tapering skyscraper above a city skyline', 1500000000.00, 'Final construction cost', '2010-01-04', 'The Burj Khalifa cost about $1.5 billion to build. At 828 meters (2,717 feet) it has been the world''s tallest building since it opened on January 4, 2010.', 'Dubai officially opens the world''s tallest tower', 'Al Arabiya', 'https://www.alarabiya.net/articles/2010%2F01%2F04%2F96241', 'the final cost of the world''s tallest tower stood at $1.5 billion', ''),
      ('pack2-eras-tour-gross', 'hard', 'entertainment', 'How much money did Taylor Swift''s Eras Tour make in ticket sales?', 'Total ticket sales (gross) across all 149 shows in 2023 and 2024, as reported by Pollstar.', '/items/stadium-concert.svg', 'Illustration of a stadium concert stage at night with a crowd in front', 2200000000.00, 'Total tour gross reported by Pollstar', '2024-12-09', 'Pollstar reported the Eras Tour grossed $2.2 billion from 10.1 million tickets over 149 shows, the highest-grossing tour ever. Billboard''s count was slightly lower, about $2.08 billion.', 'Taylor Swift''s ''Eras Tour'' Smashes All-Time Touring Record, Surpasses $2 Billion', 'Pollstar', 'https://news.pollstar.com/2024/12/09/taylor-swifts-eras-tour-sets-all-time-touring-record-breaking-2b/', 'came in at $2.2 billion and 10.055 million', 'Sources differ (Pollstar $2.2B, Billboard about $2.077B); the question names Pollstar.')
    ) as t(slug, difficulty, cat, prompt, context, image, image_alt, amount, definition, ref_date, explanation,
           src_title, src_publisher, src_url, src_excerpt, src_notes)
  loop
    insert into public.questions (slug, prompt, context, difficulty, category_id, image_url, image_alt, image_credit, status, is_sample)
    values (r.slug, r.prompt, r.context, r.difficulty, (select id from public.categories where slug = r.cat),
            r.image, r.image_alt, 'Illustration: Pricele', 'draft', false)
    on conflict (slug) do nothing
